import React, {useState, useEffect} from 'react'


export default function Filters({setFilter, categories}){

    return(
        <div>
            {
                categories.map(category,index)(
                    <button onClick={()=>setFilter({category})}>{category}</button>
                )
            }

        </div>
    )
}
